-- PostgreSQL schema for the normalized output generated by analyze_sales.py.
-- Grain: one retained transaction line; shipping-charge rows are explicitly classified.
CREATE TABLE IF NOT EXISTS retail_transactions (
    invoice_no       TEXT NOT NULL,
    stock_code       TEXT,
    description      TEXT,
    quantity         NUMERIC(14, 3) NOT NULL,
    invoice_date     TIMESTAMP NOT NULL,
    unit_price       NUMERIC(14, 4) NOT NULL,
    customer_id      BIGINT,
    country          TEXT,
    line_revenue     NUMERIC(18, 4) NOT NULL,
    line_type        TEXT NOT NULL CHECK (line_type IN ('Merchandise', 'Postage / shipping'))
);
CREATE INDEX IF NOT EXISTS idx_retail_invoice_date ON retail_transactions (invoice_date);
CREATE INDEX IF NOT EXISTS idx_retail_country ON retail_transactions (country);
CREATE INDEX IF NOT EXISTS idx_retail_stock_code ON retail_transactions (stock_code);
CREATE INDEX IF NOT EXISTS idx_retail_line_type ON retail_transactions (line_type);
